package com.hrms.attendance.controller;
import com.hrms.attendance.dto.*;import com.hrms.attendance.service.AttendanceService;import com.hrms.common.responses.*;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import io.swagger.v3.oas.annotations.tags.Tag;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.time.LocalDate;
@RestController @RequestMapping("/api/v1/admin/employees/{employeeId}/attendance") @Tag(name="Admin employee attendance") @SecurityRequirement(name="bearerAuth") @PreAuthorize("hasRole('ADMIN')")
public class AdminEmployeeAttendanceController {private final AttendanceService service;private final ClockSource clock;public AdminEmployeeAttendanceController(AttendanceService s,ClockSource c){service=s;clock=c;}
 @GetMapping public ApiResponse<AttendancePageResponse> history(@PathVariable String employeeId,@RequestParam(required=false)LocalDate fromDate,@RequestParam(required=false)LocalDate toDate,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="workDate")String sortBy,@RequestParam(defaultValue="desc")String sortDirection){return ApiResponse.success("Employee attendance history retrieved",service.employeeHistory(employeeId,fromDate,toDate,page,limit,sortBy,sortDirection),clock);}}
